from pathlib import Path
from pypdf import PdfReader
files = [
    Path('assets/uploads/2e43ce66_1-s2.0-S0926337324011780-main.pdf'),
    Path('assets/uploads/91550f0f_Optimized the e occupancy of Co active site through 4f–2p–3d gradient orbital coupling for efficient Fenton-like catalysis.pdf'),
    Path('assets/uploads/9c4ca55a_Breaking the oxo-wall for Co(IV)-oxo species and their nanoconfined catalytic performance within Ce-Co lamellar membrane.pdf'),
]
for f in files:
    print('\n' + '='*80)
    print(f.name)
    try:
        r = PdfReader(str(f))
        print('pages:', len(r.pages))
        text = ''
        for i in range(min(2, len(r.pages))):
            try:
                text += r.pages[i].extract_text() + '\n'
            except Exception as e:
                text += f'[page {i+1} extract error: {e}]\n'
        text = ' '.join(text.split())
        print(text[:5000])
    except Exception as e:
        print('ERROR', e)
